def:pub toModelInfo(raw: dict[str, object]) -> dict[str, object] {
    capabilities: dict[str, object] = {};
    return {
        "model": raw["model"] if isinstance(raw.get("model"), str) else "",
        "provider": raw["provider"] if isinstance(raw.get("provider"), str) else "",
        "capabilities": capabilities,
    };
}

def:pub toModelAssignmentResult(raw: dict[str, object]) -> dict[str, object] {
    result: dict[str, object] = {"ok": raw.get("ok") == True};
    if isinstance(raw.get("scope"), str) {
        result["scope"] = raw["scope"];
    }
    if isinstance(raw.get("provider"), str) {
        result["provider"] = raw["provider"];
    }
    if isinstance(raw.get("model"), str) {
        result["model"] = raw["model"];
    }
    if raw.get("confirm_required") == True {
        result["confirm_required"] = True;
        if isinstance(raw.get("confirm_message"), str) {
            result["confirm_message"] = raw["confirm_message"];
        }
    }
    return result;
}
