def:pub FoodSort() -> JsxElement {
    has isDrawerOpen: bool = False;
    has selectedOption: str = "createdAt";

    pathname = usePathname();
    router = useRouter();

    def onValueChange(value: str) {
        selectedOption = value;
        handleSort(value);
    }

    def onOpenChange(open: bool) {
        isDrawerOpen = open;
    }

    def handleSort(term: str) {
        nextPath = (pathname as str) + ("?sort=" + term if term else "");
        router.replace(nextPath as Route);
    }

    return <>
        <SelectionDrawerRoot open={isDrawerOpen} onOpenChange={onOpenChange}>
            <SelectionDrawerTrigger asChild={True}>
                <button className="flex items-center max-w-full">
                    <span className="truncate">{sortOptions[selectedOption]}</span>
                    <Icon icon={IconCaretDown} size={2.5} color="gray-dark" />
                </button>
            </SelectionDrawerTrigger>
            <SelectionDrawerContent>
                <SelectionDrawerRadioGroup value={selectedOption} onValueChange={onValueChange}>
                    {for (key, label) in sortOptions.items() {
                        <SelectionDrawerRadioGroupItem key={key} value={key}>
                            <Label>{label}</Label>
                        </SelectionDrawerRadioGroupItem>
                    }}
                </SelectionDrawerRadioGroup>
            </SelectionDrawerContent>
        </SelectionDrawerRoot>
    </>;
}
