    merged_style: dict[str, object] = {**(style if style else {})};
    if isinstance(gap, int) {
        merged_style["gap"] = f"{gap}px";
    }
    if bgColor {
        merged_style["backgroundColor"] = bgColor;
    }
    return (
        <div
            className={classNames(
                "flex flex-wrap items-center",
                {"flex-col": direction == "vertical"},
                justifyClass[justify if justify else "start"],
                alignClass[align if align else "stretch"],
                gap_cls,
                className,
            )}
            style={merged_style}
        >
            {children}
        </div>
    );
}
