import from "react" { useMemo }
import from "fuse.js" { default as Fuse, FuseOptionKey }

glob DEFAULT_LIMIT = 20;
glob DEFAULT_THRESHOLD = 0.34;

obj SearchableMovieItem {
    has title: str;
    has year: str | None = None;
    has genres: list[str] | None = None;
    has overview: str | None = None;
    has cast: list[str] | None = None;
}

glob DEFAULT_FUSE_KEYS: list[dict[str, float | str]] = [
    {"name": "title", "weight": 0.65},
    {"name": "genres", "weight": 0.15},
    {"name": "overview", "weight": 0.1},
    {"name": "cast", "weight": 0.1}
];

def fuseSearchResults(fuse: object, normalized: str, limit: int) -> list[dict[str, object]] {
    search = getattr(fuse, "search");
    return search(normalized, {"limit": limit}) as list[dict[str, object]];
}

def:pub useMovieSearch[T](items: list[T], query: str, options: dict[str, object] | None = None) -> list[T] {
    opts = options or {};
    limit = opts.get("limit", DEFAULT_LIMIT) as int;
    threshold = opts.get("threshold", DEFAULT_THRESHOLD) as float;
    keys = opts.get("keys");
    fuse = useMemo(lambda () -> object {
        return Fuse(items, {
            "includeScore": True,
            "threshold": threshold,
            "shouldSort": True,
            "ignoreLocation": True,
            "minMatchCharLength": 2,
            "keys": keys or DEFAULT_FUSE_KEYS
        });
    }, [items, keys, threshold]);
    return useMemo(lambda () -> list[T] {
        normalized = query.strip();
        if not normalized {
            return items[0:limit];
        }
        return [row["item"] as T for row in fuseSearchResults(fuse, normalized, limit)];
    }, [fuse, items, limit, query]);
}
