glob SAFE_ATTACHMENT_FALLBACK = "attachment";

glob ALLOWED_ATTACHMENT_MIME_TYPES: set[str] = {
    "application/json",
    "application/pdf",
    "text/csv",
    "text/markdown",
    "text/plain",
    "image/gif",
    "image/jpeg",
    "image/png",
    "image/webp",
};

glob ALLOWED_ATTACHMENT_MIME_PREFIXES: list[str] = ["text/"];

def:pub attachmentTooLargeMessage(name: str) -> str {
    return f"{name} is too large to upload (max {MAX_ATTACHMENT_MIB} MB).";
}

def:pub tooManyAttachmentsMessage() -> str {
    return f"Only {MAX_ATTACHMENTS_PER_SELECTION} files can be attached at once.";
}

def:pub unsupportedAttachmentTypeMessage(name: str, mimeType: str) -> str {
    type_label = mimeType if mimeType else "unknown type";
    return f"{name} cannot be uploaded ({type_label} is not an allowed attachment type).";
}

obj FileLike {
    has type: str = "";
}

def:pub isAllowedAttachmentMime(file: FileLike) -> bool {
    mime_type = str(file.type or "").strip().lower();
    if not mime_type { return False; }
    if mime_type in ALLOWED_ATTACHMENT_MIME_TYPES { return True; }
    for prefix in ALLOWED_ATTACHMENT_MIME_PREFIXES {
        if mime_type.startswith(prefix) { return True; }
    }
    return False;
}

import unicodedata;
import re;

def:pub safeAttachmentBasename(name: str) -> str {
    base = unicodedata.normalize("NFKC", str(name or ""));
    base = re.sub("[\u202a-\u202e\u2066-\u2069\u200b-\u200d\ufeff]+", "", base);
    base = re.sub("[/\\?%*:|\"<>]", "_", base).strip();
    return base if base else SAFE_ATTACHMENT_FALLBACK;
}
