import random;

def:pub shuffleArray[T](array: list[T]) -> list[T] {
    copy = [*array];
    i = len(copy) - 1;
    while i > 0 {
        j = int(random.random() * (i + 1));
        temp = copy[i];
        copy[i] = copy[j];
        copy[j] = temp;
        i -= 1;
    }
    return copy;
}
