            if (_hr < 10) {
                _hr = '0' + _hr;
            }

            return ` ${_hr}`;
        })();
        timeString += (() => {
            let _mins: any = datetime.getMinutes();
            if (_mins < 10) {
                _mins = '0' + _mins;
            }
            return `:${_mins}`;
        })();

        if (_options.timeFormat12hr) {
            timeString += (() => {
                const _hr = datetime.getHours();
                if (_hr < 12) return ' AM';
                else return ' PM';
            })();
        }
    }

    // return `${datetime.getDate()} | ${timeString}`;
    return timeString;
