                                        );
                                    })
                                        .then(() => resolve(db))
                                        .catch((err) => reject(err));
                                });
                        })
                        .catch((err: any) => reject(err));
                })
                .catch((err: any) => reject(err));
        });
    }

    closeDatabase(db: SQLiteDatabase | null): void {
