                                    prodName: row.prodName,
                                    prodDesc: row.prodDesc,
                                    prodImage: row.prodImage,
                                    prodPrice: row.prodPrice,
                                });
                            }
                            resolve(products);
                        });
                    })
                        .then(() => this.closeDatabase(db))
                        .catch((err) => reject(err));
                })
                .catch((err) => reject(err));
        });
