                .then((db) => {
                    db.transaction((tx) => {
                        tx.executeSql('SELECT * FROM Product WHERE prodId = ?', [id]).then(([_, results]) => {
                            if (results.rows.length > 0) {
                                resolve(results.rows.item(0));
                            } else {
                                reject('Product not found');
                            }
