                            'INSERT INTO Product (prodId, prodName, prodDesc, prodImage, prodPrice) VALUES (?, ?, ?, ?, ?)',
                            [prod.prodId, prod.prodName, prod.prodDesc, prod.prodImage, prod.prodPrice]
                        ).then(([_, result]) => resolve(result));
