import from "react" { createContext, useContext, useId }
import from "@radix-ui/react-slot" { Slot }
import from "react-hook-form" { Controller, FormProvider, useFormContext, useFormState }
import from "@/lib/utils" { cn }
import from "@/components/ui/label" { Label }

glob FormFieldContext = createContext({"name": ""});
glob FormItemContext = createContext({"id": ""});

glob:pub Form = FormProvider;

def:pub FormField(props: dict[str, object]) -> JsxElement {
    <FormFieldContext.Provider value={{"name": props["name"]}}>
        <Controller {**props} />
    </FormFieldContext.Provider>
}

def:pub useFormField() -> dict[str, object] {
    field_context = useContext(FormFieldContext);
    item_context = useContext(FormItemContext);
    form_ctx = useFormContext();
    form_state = useFormState({"name": field_context["name"]});
    field_state = form_ctx.getFieldState(field_context["name"], form_state);
    id = item_context["id"] as str;
    return {
        "id": id,
        "name": field_context["name"],
        "formItemId": f"{id}-form-item",
        "formDescriptionId": f"{id}-form-item-description",
        "formMessageId": f"{id}-form-item-message",
        **field_state,
    };
}

def:pub FormItem(className: str = "", children: object | None = None, props: dict[str, object] | None = None) -> JsxElement {
    id = useId();
    rest = props if props is not None else {};
    <FormItemContext.Provider value={{"id": id}}>
        <div
            data-slot="form-item"
            className={cn("grid gap-2", className)}
            {**rest}
        >
            {children}
        </div>
    </FormItemContext.Provider>
}

def:pub FormLabel(className: str = "", props: dict[str, object] | None = None) -> JsxElement {
    rest = props if props is not None else {};
    field = useFormField();
    error = field["error"];
    form_item_id = field["formItemId"] as str;
    <Label
        data-slot="form-label"
        data-error={bool(error)}
        className={cn("data-[error=true]:text-destructive", className)}
        htmlFor={form_item_id}
        {**rest}
    />
}

def:pub FormControl(props: dict[str, object] | None = None) -> JsxElement {
    rest = props if props is not None else {};
    field = useFormField();
    error = field["error"];
    form_item_id = field["formItemId"] as str;
    form_description_id = field["formDescriptionId"] as str;
    form_message_id = field["formMessageId"] as str;
    aria_describedby = form_description_id if not error else f"{form_description_id} {form_message_id}";
    <Slot
        data-slot="form-control"
        id={form_item_id}
        aria-describedby={aria_describedby}
        aria-invalid={bool(error)}
        {**rest}
    />
}

def:pub FormDescription(className: str = "", props: dict[str, object] | None = None) -> JsxElement {
    rest = props if props is not None else {};
    field = useFormField();
    form_description_id = field["formDescriptionId"] as str;
    <p
        data-slot="form-description"
        id={form_description_id}
        className={cn("text-muted-foreground text-sm", className)}
        {**rest}
    />
}

def:pub FormMessage(className: str = "", children: object | None = None, props: dict[str, object] | None = None) -> JsxElement | None {
    rest = props if props is not None else {};
    field = useFormField();
    error = field["error"];
    form_message_id = field["formMessageId"] as str;
    body = str((error as dict[str, object]).get("message", "")) if error else children;
    if not body {
        return None;
    }
    <p
        data-slot="form-message"
        id={form_message_id}
        className={cn("text-destructive text-sm", className)}
        {**rest}
    >
        {body}
    </p>
}
