def returnFontSizeRatio(fontSize: str) -> float {
    if fontSize.endswith("px") {
        parseFontSize = float(fontSize.replace("px", ""));
        floatFontSize = parseFontSize if not Number.isNaN(parseFontSize) else 16;
        return floatFontSize / 16;
    } elif fontSize.endswith("rem") or fontSize.endswith("em") {
        parseFontSize = float(re.sub("rem|em", "", fontSize));
        floatFontSize = parseFontSize if not Number.isNaN(parseFontSize) else 1;
        return floatFontSize;
    }
    mapped = FONT_SIZE_MAP.get(fontSize);
    if mapped is not None {
        return mapped / 16;
    }
    parsed = float(fontSize) if fontSize else 16;
    parseFontSize = parsed if not Number.isNaN(parsed) else 16;
    return parseFontSize / 16;
}

def:pub useFontSize() -> Callable[[str], str] {
    has isWideScreen: bool = _initial_wide_screen();

    useEffect(lambda {
        def handle_resize() -> None {
            ratio = window.innerWidth / window.innerHeight;
            isWideScreen = ratio >= 16 / 9;
        }
        window.addEventListener("resize", handle_resize);
        return lambda { window.removeEventListener("resize", handle_resize); };
    }, []);

    def resolve(variable: str) -> str {
        trimVariable = variable.strip();
        if trimVariable.endswith("%") or trimVariable == "auto" {
            return trimVariable;
        }
        fontSizeRatio = returnFontSizeRatio(trimVariable);
        if isWideScreen {
            return f"calc({fontSizeRatio} * (100vh / 37))";
        }
        return f"calc({fontSizeRatio} * (150vw / 100))";
    }

    return resolve;
}
