    if not el { return; }
    el.scrollIntoView({"behavior": "smooth", "block": "start"});
    el.classList.add("ring-2", "ring-brand", "rounded-md");
    window.setTimeout(lambda { el.classList.remove("ring-2", "ring-brand", "rounded-md"); }, 1600);
}

def:pub HashScroll() -> None {
    useEffect(lambda {
        if window.location.hash { window.setTimeout(scroll, 60); }
        window.addEventListener("hashchange", scroll);
        return lambda { window.removeEventListener("hashchange", scroll); };
    }, []);
    return None;
}
