    issues = error["issues"] as list[object];
    for issue in issues {
        issue_dict = issue as dict[str, object];
        path_list = issue_dict["path"] as list[object];
        path = (".".join([str(p) for p in path_list]) or "form");
        errors[path] = issue_dict["message"] as str;
    }
    return errors;
}
